#!/bin/sh
# The 10-species check of the collapsed shift step (README.md): replicates 1
# to 5 of base_cm_m3 and base_rare_cm_m3 at 5,000 + 5,000 with the step on,
# keeping draws, with ../mu-b0-shift-20261018/refit-s100.R unchanged.
# 5 workers, one RcppParallel thread and one BLAS thread per fit.
# Launched detached from a non-interactive shell:
#   nohup perl -MPOSIX -e 'POSIX::setsid() or die; exec @ARGV or die' sh launch.sh > launch.log 2>&1 < /dev/null &
# Do not edit this file while it is running: sh reads it lazily.
set -u
STEP=s10
WT=/Users/douglasyu/src/occJSDM/.worktrees/mu-b0-shift-s10
RUN=$WT/dev/simstudy/mu-b0-shift-s10-20261018
REFIT=$WT/dev/simstudy/mu-b0-shift-20261018/refit-s100.R
RSCRIPT=/usr/local/bin/Rscript
ARMS=base_cm_m3,base_rare_cm_m3
REPS=1-5; NB=5000; NI=5000; CORES=5
OUT=$RUN/draws/$STEP
export VECLIB_MAXIMUM_THREADS=1
export RCPP_PARALLEL_NUM_THREADS=1
cd "$RUN"
if [ -e "$OUT" ]; then echo "refusing: $OUT exists" >&2; exit 1; fi
if pgrep -f 'refit-s100.R|refit-drift.R|run_study.R' > /dev/null; then echo "refusing: another study is running" >&2; exit 1; fi
{
  echo "step: $STEP"
  echo "launched: $(date '+%F %T')"
  echo "revision: $(git -C "$WT" rev-parse HEAD)"
  echo "branch: $(git -C "$WT" rev-parse --abbrev-ref HEAD)"
  echo "dirty files: $(git -C "$WT" status --porcelain | wc -l | tr -d ' ')"
  echo "R: $("$RSCRIPT" -e 'cat(R.version.string)')"
  echo "BLAS: $("$RSCRIPT" -e 'cat(extSoftVersion()[["BLAS"]])')"
  echo "VECLIB_MAXIMUM_THREADS seen by R: $("$RSCRIPT" -e 'cat(Sys.getenv("VECLIB_MAXIMUM_THREADS"))')"
  echo "lowpowermode: $(pmset -g | awk '/lowpowermode/ {print $2}')"
  echo "power: $(pmset -g batt | head -1)"
  echo "other R processes at launch: $(ps -eo pcpu,args | grep -E 'exec/R|Rscript' | grep -v grep | awk '$1 > 5' | wc -l | tr -d ' ') using over 5% CPU"
  echo "settings: replicates $REPS of $ARMS, nburn = $NB, niter = $NI, nchain = 2, cores = $CORES, threads = 1, b0_shift at its defaults"
} > "$STEP-provenance.txt"
echo $$ > "$STEP-launcher.pid"
"$RSCRIPT" "$REFIT" "$WT" "$OUT" "$CORES" "$ARMS" "$REPS" "$NB" "$NI" > "$STEP.log" 2>&1 &
RPID=$!
echo $RPID > "$STEP-rscript.pid"
caffeinate -i -w $RPID &
wait $RPID
status=$?
echo "exit status: $status at $(date '+%F %T')" >> "$STEP-provenance.txt"
echo "ALL DONE $(date '+%F %T') status $status" >> "$STEP.log"
